package com.metcoffee.model;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document;
@Document("direcciones") public class Direccion { @Id private String id; private String usuarioId,etiqueta,destinatario,direccion,telefono; private boolean principal; public Direccion(){} public Direccion(String id,String u,String e,String d,String a,String t,boolean p){this.id=id;usuarioId=u;etiqueta=e;destinatario=d;direccion=a;telefono=t;principal=p;} public String getId(){return id;} public String getUsuarioId(){return usuarioId;} public String getEtiqueta(){return etiqueta;} public String getDestinatario(){return destinatario;} public String getDireccion(){return direccion;} public String getTelefono(){return telefono;} public boolean isPrincipal(){return principal;} public void setId(String v){id=v;} public void setUsuarioId(String v){usuarioId=v;} public void setEtiqueta(String v){etiqueta=v;} public void setDestinatario(String v){destinatario=v;} public void setDireccion(String v){direccion=v;} public void setTelefono(String v){telefono=v;} public void setPrincipal(boolean v){principal=v;} }
